  "સ્વતંત્ર સાયબર જાગૃતિ પહેલ — આ સત્તાવાર સરકારી કે પોલીસ વેબસાઇટ નથી. સત્તાવાર ફરિયાદ નોંધણી માટે cybercrime.gov.in અથવા ૧૯૩૦ પર સંપર્ક કરો.": {
    "gu": "સ્વતંત્ર સાયબર જાગૃતિ પહેલ — આ સત્તાવાર સરકારી કે પોલીસ વેબસાઇટ નથી. સત્તાવાર ફરિયાદ નોંધણી માટે cybercrime.gov.in અથવા ૧૯૩૦ પર સંપર્ક કરો.",
    "hi": "स्वतंत्र साइबर जागरूकता पहल — यह आधिकारिक सरकारी या पुलिस वेबसाइट नहीं है। आधिकारिक शिकायत दर्ज करने के लिए cybercrime.gov.in पर जाएँ या १९३० पर संपर्क करें।",
    "en": "Independent cyber awareness initiative — this is not an official government or police website. To file an official complaint, visit cybercrime.gov.in or call 1930."
  },
  "કોઈપણ શંકાસ્પદ WhatsApp સંદેશો, બેંક લિંક કે QR કોડ તપાસો સેકન્ડોમાં. ડિજિટલ અરેસ્ટ, બનાવટી લોન અને UPI છેતરપિંડીથી તમારા પરિવારને સુરક્ષિત રાખો.": {
    "gu": "કોઈપણ શંકાસ્પદ WhatsApp સંદેશો, બેંક લિંક કે QR કોડ તપાસો સેકન્ડોમાં. ડિજિટલ અરેસ્ટ, બનાવટી લોન અને UPI છેતરપિંડીથી તમારા પરિવારને સુરક્ષિત રાખો.",
    "hi": "किसी भी संदिग्ध WhatsApp संदेश, बैंक लिंक या QR कोड की कुछ ही सेकंड में जाँच करें। डिजिटल अरेस्ट, नकली ऋण और UPI धोखाधड़ी से अपने परिवार को सुरक्षित रखें।",
    "en": "Check any suspicious WhatsApp message, bank link, or QR code in seconds. Protect your family from digital arrest scams, fake loans, and UPI fraud."
  },
