  "ગુજરાતના નાગરિકો, વરિષ્ઠ વડીલો અને વેપારીઓ માટે સમર્પિત સ્વતંત્ર સાયબર જાગૃતિ સહાયક. આ એક શૈક્ષણિક પહેલ છે અને સત્તાવાર ફરિયાદ માટે ભારત સરકારના પોર્ટલ cybercrime.gov.in અથવા ૧૯૩૦ નો સંદર્ભ આપે છે.": {
    "gu": "ગુજરાતના નાગરિકો, વરિષ્ઠ વડીલો અને વેપારીઓ માટે સમર્પિત સ્વતંત્ર સાયબર જાગૃતિ સહાયક. આ એક શૈક્ષણિક પહેલ છે અને સત્તાવાર ફરિયાદ માટે ભારત સરકારના પોર્ટલ cybercrime.gov.in અથવા ૧૯૩૦ નો સંદર્ભ આપે છે.",
    "hi": "गुजरात के नागरिकों, वरिष्ठ नागरिकों और व्यापारियों के लिए समर्पित स्वतंत्र साइबर जागरूकता सहायक। यह एक शैक्षिक पहल है और आधिकारिक शिकायतों के लिए भारत सरकार के पोर्टल cybercrime.gov.in या हेल्पलाइन 1930 का संदर्भ देता है।",
    "en": "An independent cyber awareness assistant for the citizens, senior residents, and businesses of Gujarat. This educational initiative refers users to the Government of India portal cybercrime.gov.in or helpline 1930 for official complaints."
  },
