    "hi": "बिना आधार-पैन के 5 मिनट में लोन देने का झाँसा देकर ऐप आपकी तस्वीरें और संपर्क चुरा सकते हैं, फिर बदली तस्वीरें भेजने की धमकी देते हैं।",
