    "hi": "अहमदाबाद के नवरंगपुरा में 71 वर्षीय सेवानिवृत्त प्रोफेसर को चार दिन होटल के कमरे में “डिजिटल अरेस्ट” रखकर ₹82 लाख ट्रांसफ़र करवाए गए। लोगों को सतर्क करने के लिए इस मामले की नकली मुहर और WhatsApp DP दिखाई गई है।",
