    "hi": "प्रिय परिवारजनों, यदि किसी अनजान नंबर से वीडियो कॉल आए और वर्दीधारी व्यक्ति खुद को CBI, मुंबई क्राइम ब्रांच या कस्टम्स अधिकारी बताकर कहे कि पार्सल में ड्रग्स मिले हैं और आपको डिजिटल अरेस्ट किया जा रहा है:",
